-- Master-only authoring workspace for the ten GREEN CITY phase modules.
create table public.phase_module_configs (
  phase_number smallint primary key check (phase_number between 1 and 10),
  region_name text not null,
  theme text not null,
  challenge text not null,
  learning_problem text not null default '',
  learning_goals text[] not null default '{}',
  mission_outline text not null default '',
  professions text not null default '',
  economy_notes text not null default '',
  scenario_notes text not null default '',
  content_status text not null default 'planning'
    check (content_status in ('planning', 'draft', 'review', 'approved')),
  updated_by uuid references auth.users(id) on delete set null,
  updated_at timestamptz not null default now()
);

insert into public.phase_module_configs
  (phase_number, region_name, theme, challenge, learning_problem, learning_goals, mission_outline, professions, economy_notes, scenario_notes, content_status)
values
(1,'Centro Industrial','Energia e resíduos','Organizar a coleta, modernizar prédios com energia solar e eletrificar a frota municipal.','Resíduos sem destinação adequada e consumo de energia e combustíveis pressionam o ambiente.',array['Reconhecer categorias de resíduos e destinos.','Entender coleta seletiva e EcoCentro.','Relacionar energia solar, mobilidade elétrica e emissões.'],'Investigar; recolher cinco resíduos; entregar no EcoCentro; solarizar oito prédios; converter o veículo.','Agente ambiental, coletor, cooperado, eletricista solar, gestor de mobilidade.','Reciclagem e energia limpa exigem infraestrutura, investimento e manutenção; CIT é pontuação fictícia.','EcoCentro, cinco categorias de resíduos, telhados solares e base de eletrificação.','review'),
(2,'Porto','Água e logística','Controlar efluentes, instalar tratamento sanitário e coletar resíduos das empresas.','Efluentes industriais, esgoto sanitário e resíduos empresariais exigem soluções distintas.',array['Diferenciar efluente industrial de esgoto sanitário.','Dimensionar conceitualmente uma ETE segundo contaminantes.','Entender limites da fossa séptica sanitária.','Conhecer triagem e cooperativa.'],'Inspecionar três descargas; implantar ETE; atender duas instalações sanitárias isoladas; coletar três empresas; separar materiais.','Engenheiro sanitarista, químico, operador de ETE, técnico de laboratório, cooperado.','Incluir tratamento, monitoramento, manutenção e destinação de lodo; água tratada não é necessariamente potável.','Rio, descargas identificadas, ETE, instalações sanitárias, caminhão e cooperativa.','review'),
(3,'Periferia Verde','Saneamento e serviços','Ampliar coleta seletiva, saneamento e serviços urbanos.','Descarte irregular, falta de saneamento e escoamento da chuva afetam a comunidade.',array['Separar orgânicos e recicláveis secos.','Explicar manejo e tempo de compostagem.','Distinguir esgoto sanitário e drenagem pluvial.','Conhecer limites dos jardins de chuva.'],'Investigar; recolher resíduos; separar fluxos; acompanhar composteira; conectar moradias; construir jardim de chuva em local adequado.','Agente comunitário, coletor, compostador, educador, técnico de saneamento e drenagem.','Composto maturado retorna nutrientes ao solo; redes e jardins exigem implantação e manutenção.','Moradias, coleta, composteira, rede sanitária e jardim de chuva sem ligação ao esgoto.','review'),
(4,'Reserva Florestal','Biodiversidade e habitats','Restaurar habitats, proteger nascentes e conectar corredores ecológicos.','Fragmentação, queimadas e perda de vegetação reduzem abrigo, alimento e circulação das espécies.',array['Identificar habitats e relações ecológicas.','Entender fragmentação e corredores.','Diferenciar prevenção de incêndios, combate e restauração.','Reconhecer espécies nativas e monitoramento.'],'Mapear habitats; observar fauna; planejar corredor; prevenir queimadas; restaurar com espécies adequadas; monitorar.','Biólogo, engenheiro florestal, guarda-parque, brigadista, viveirista, educador.','Conservação, pesquisa, restauração e turismo responsável geram trabalho com limites ecológicos.','Trilhas, placas, viveiro nativo, pontos de monitoramento e corredor ecológico.','planning'),
(5,'Zona Costeira','Oceanos, rios e manguezais','Reduzir poluição costeira, proteger manguezais e preparar a orla para eventos extremos.','Resíduos e contaminantes percorrem bacias até rios, estuários, manguezais e oceanos.',array['Seguir a água da bacia ao oceano.','Reconhecer manguezais como berçários e proteção costeira.','Relacionar resíduos terrestres e poluição marinha.','Proteger fauna e habitats costeiros.'],'Investigar bacia; identificar fontes; acompanhar resíduos até o estuário; recuperar áreas de mangue adequadas; proteger fauna e planejar a orla.','Oceanógrafo, biólogo marinho, pescador, marisqueira, agente costeiro, gestor de áreas protegidas.','Pesca e turismo responsáveis dependem de ecossistemas saudáveis e monitoramento contínuo.','Rio, estuário, manguezal, praia, pesca, trilhas e placas de fauna.','planning'),
(6,'Cinturão Agrícola','Solo e produção sustentável','Promover manejo do solo, uso eficiente da água e produção de baixo impacto.','Erosão e manejo inadequado de água e matéria orgânica reduzem a saúde do solo.',array['Explicar como cobertura vegetal reduz erosão.','Conhecer conservação do solo e água.','Entender agroflorestas e diversidade.','Relacionar nutrientes, produção e proteção hídrica.'],'Diagnosticar erosão; analisar cobertura e declividade; planejar curvas de nível; implantar cobertura vegetal e faixas ripárias; comparar sistemas produtivos.','Agrônomo, agricultor, técnico agrícola, extensionista, operador de irrigação, viveirista.','Avaliar produtividade, custos, água, solo, mão de obra e mercado sem prometer rentabilidade.','Talhões, solo exposto e protegido, curvas de nível, agrofloresta e irrigação eficiente.','planning'),
(7,'Centro Histórico','Mobilidade e patrimônio','Reduzir emissões, melhorar caminhabilidade e preservar espaços públicos.','Trânsito, calor, energia e desenho urbano influenciam saúde e qualidade de vida.',array['Comparar modos de transporte.','Entender acessibilidade e transporte coletivo.','Reconhecer arborização e eficiência energética.','Conciliar patrimônio e adaptação climática.'],'Mapear deslocamentos; identificar conflitos; redesenhar travessias; melhorar transporte e ciclovias; ampliar sombra e eficiência energética.','Urbanista, arquiteto, engenheiro de tráfego, guia cultural, servidor de mobilidade, comerciante.','Comércio, transporte coletivo e turismo cultural dependem de espaços seguros e acessíveis.','Praças, prédios históricos, calçadas, ciclovias, transporte coletivo e árvores.','planning'),
(8,'Distrito Tecnológico','Economia circular e logística reversa','Incentivar reuso, energia limpa e inovação industrial.','Eletrônicos, baterias, pneus e embalagens descartados incorretamente desperdiçam recursos e podem causar riscos.',array['Distinguir resíduos comuns e logística reversa.','Conhecer pontos de recebimento e operadores especializados.','Entender desmontagem, triagem, reuso e reciclagem.','Reconhecer responsabilidades de consumidores, comércio, fabricantes e governo.'],'Classificar eletrônicos, baterias, pneus e embalagens; encaminhar cada fluxo a recebimento adequado; acompanhar triagem e recuperação.','Técnico eletrônico, reciclador especializado, engenheiro de materiais, operador logístico, projetista.','Reparo e recuperação mantêm valor; baterias e perigosos exigem transporte e processamento especializados.','Pontos de entrega, oficina, triagem e área segura de baterias e pneus.','planning'),
(9,'Vale das Nascentes','Água doce, bacias e gestão ambiental','Proteger nascentes, recuperar matas ciliares e controlar erosão.','Nascentes degradadas e margens sem vegetação comprometem quantidade e qualidade da água.',array['Relacionar nascente, curso e bacia hidrográfica.','Reconhecer função da mata ciliar.','Entender monitoramento da água.','Conhecer avaliação e licenciamento quando exigido.'],'Delimitar microbacia; investigar nascentes; registrar parâmetros; recuperar margens conforme diagnóstico; mapear pressões e acompanhar medidas.','Hidrogeólogo, geógrafo, técnico de laboratório, engenheiro ambiental, fiscal, produtor rural.','Proteção e monitoramento têm custos permanentes e responsabilidades compartilhadas.','Nascentes, mata ciliar, estações de monitoramento e sinalização da bacia.','planning'),
(10,'Ilha da Biodiversidade','Gestão integrada, clima e economia circular','Consolidar recuperação ecológica e equilibrar turismo, comunidades e conservação.','Decisões isoladas não resolvem desafios climáticos, sociais, econômicos e ecológicos interligados.',array['Relacionar clima, biodiversidade, água, energia e resíduos.','Compreender economia circular e governança.','Diferenciar papéis de cidadãos, empresas e governo.','Avaliar resultados e compromissos de longo prazo.'],'Construir plano integrado; comparar indicadores; negociar compromissos; equilibrar turismo e conservação; apresentar resultados e pendências.','Gestor de conservação, cientista climático, empreendedor de impacto, liderança comunitária, auditor, educador.','Distinguir faturamento, custos, lucro, benefícios coletivos e investimentos de longo prazo.','Centro de pesquisa, visitação controlada, habitats restaurados, sistemas de energia e água, painel de indicadores.','planning')
on conflict (phase_number) do nothing;

alter table public.phase_module_configs enable row level security;
revoke all on table public.phase_module_configs from anon, public;
grant select, update on table public.phase_module_configs to authenticated;

create policy "Master reads phase module configurations"
  on public.phase_module_configs for select to authenticated
  using ((select private.is_master()));

create policy "Master updates phase module configurations"
  on public.phase_module_configs for update to authenticated
  using ((select private.is_master()))
  with check ((select private.is_master()));
